"""Generate a review report from retained raw results, never from hand-entered gains."""
import html
import json
from pathlib import Path
import statistics

p=Path(__file__).resolve().parent
load=lambda n:json.loads((p/n).read_text())
matrix=load('paired-cast-final-cpu2-summary.json')
persistent=load('paired-cast-confirmation-cpu2-summary.json')['conditions'][0]
fresh=load('paired-cast-confirmation-fresh-cpu2-summary.json')['conditions'][0]
aa=load('paired-cast-final-cpu2-aa-summary.json')['conditions'][0]
passed=lambda s:s['median_cpu_time_reduction_percent']>=3 and s['cpu_speedup_ci95'][0]>1
accepted=passed(persistent) and passed(fresh) and aa['cpu_speedup_ci95'][0]<=1<=aa['cpu_speedup_ci95'][1] and not any(s['reliable_cpu_regression_over_2_percent'] for s in matrix['conditions'])
e2e=load('e2e-summary.json')
meta=load('branch-metadata.json')

def row(label,s,link):
    lo,hi=s['cpu_speedup_ci95']
    return f'<tr><td>{html.escape(label)}</td><td>{s["documents_per_run"]:,}</td><td>{s["batch_size"]}</td><td>{s["pairs"]}</td><td>{s["median_cpu_time_reduction_percent"]:.2f} %</td><td>{lo:.4f}–{hi:.4f}×</td><td><a href="{link}">brut</a></td></tr>'

rows=row('Témoin A/A',aa,'paired-cast-final-cpu2-aa.jsonl')
rows+=''.join(row(s['case'],s,'paired-cast-final-cpu2.jsonl') for s in matrix['conditions'])
rows+=row('Confirmation, processus persistants',persistent,'paired-cast-confirmation-cpu2.jsonl')
rows+=row('Confirmation, processus neufs',fresh,'paired-cast-confirmation-fresh-cpu2.jsonl')
verdict=('Les seuils prédéfinis sont atteints sur les deux confirmations. Le gain reste propre aux charges et à la machine testées.' if accepted else 'Le candidat ne franchit pas tous les seuils prédéfinis. Le conserver comme expérience ; aucune revendication de gain ETL robuste ni proposition de fusion en l’état.')
e2e_rows=''.join(f'<tr><td>{key}</td><td>{value["median_time_reduction_percent"]:.2f} %</td><td>'+', '.join(f'{x:.4f}×' for x in value['paired_speedups'])+'</td></tr>' for key,value in e2e['metrics'].items())

text=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><title>GraFlo — optimisation du casting</title>
<style>body{{font:16px/1.55 system-ui,sans-serif;max-width:1120px;margin:40px auto;padding:0 24px;color:#182638;background:#fbfcff}}h1,h2{{line-height:1.25}}h2{{margin-top:32px}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{border-bottom:1px solid #d7dfeb;padding:9px;text-align:left}}th{{background:#eaf0f9}}a{{color:#175cb5}}code{{overflow-wrap:anywhere}}.verdict{{background:#eaf0f9;padding:18px;border-left:4px solid #276ac5}}img{{width:100%;height:auto}}li{{margin:7px 0}}small{{color:#526278}}</style>
<h1>Optimisation du casting GraFlo</h1><p>29 octobre 2026 · branche locale <code>perf/casting-hot-path</code> · référence <code>12431f62124988ddd12a949841ef55d9c956ace3</code></p>
<p class="verdict">{verdict}</p>
<p>Commit préparé : <code>{meta['commit']}</code>. La modification vise les fusions répétées observées par le profil : spécialisation des listes ordinaires de dictionnaires et déplacement des quatre fonctions internes hors de chaque appel. Les fragments vides sont conservés jusqu’au moment de leur fusion. Les validations, identités, copies superficielles, unions, ordres et canaux de provenance gardent leur comportement dans les cas vérifiés. Le chemin général traite toujours les VertexRep et sous-classes.</p>
<h2>Mesures contrôlées</h2><p>Temps CPU du casting inline, un cœur. Une réduction positive signifie moins de temps CPU. L’accélération est le rapport référence/candidat ; la baisse affichée est, par convention, 100 × (1 − 1 / médiane des rapports appariés). Avec un nombre pair de paires, cette transformation peut différer légèrement de la médiane des baisses individuelles. L’IC95 est obtenu par 10 000 rééchantillonnages des paires, graine 20261029. Il ne constitue pas une preuve universelle et les intervalles des charges secondaires ne sont pas corrigés pour comparaisons multiples.</p>
<p>Le seuil annoncé avant mesure est une baisse médiane CPU d’au moins 3 % et une borne basse d’IC95 d’accélération supérieure à 1 sur 50 000 documents. Toute régression CPU fiable supérieure à 2 % est signalée. La confirmation supplémentaire renouvelle les deux interpréteurs à chaque paire et équilibre leur ordre de création ; sa graine de hash est identique dans chaque paire et varie sur 12 valeurs. Les intervalles des processus persistants ne couvrent pas la variabilité entre processus.</p>
<img src="casting-comparison.svg" alt="Rapports CPU appariés et intervalles de confiance, avec témoin A/A">
<table><thead><tr><th>Charge</th><th>Docs/passage</th><th>Lot</th><th>Paires</th><th>Baisse CPU médiane</th><th>IC95 accélération</th><th>Preuve</th></tr></thead><tbody>{rows}</tbody></table>
<p>Même CPU logique 2 avant import et création des threads, ordre AB/BA équilibré, données et dépendances identiques. Imports, échauffement, GC préalable et vérification sont hors intervalle ; le GC normal reste actif. Toutes les paires et tous les passages défavorables sont conservés. Le contrôle A/A affiche {aa['median_cpu_time_reduction_percent']:.2f} % de baisse apparente mais son intervalle inclut 1 : un petit écart isolé reste peu probant.</p>
<p>La confirmation persistante affiche {persistent['median_cpu_time_reduction_percent']:.2f} % de baisse médiane, avec un intervalle large incluant une régression et un gain ; la confirmation en processus neufs affiche {fresh['median_cpu_time_reduction_percent']:.2f} %, avec un intervalle excluant 1. Ce désaccord interdit d’annoncer un gain robuste global selon les critères retenus.</p>
<p>Sources et protocoles : <a href="paired-protocol-final.json">configuration et empreintes</a>, <a href="cpu-control-before-runs.txt">placement et critères</a>, <a href="fresh-process-confirmation-before-run.txt">renouvellement des processus</a>, <a href="environment-final.json">environnement</a>. La méthode initiale sur cpuset 2,3 laissait migrer les threads ; ses résultats exploratoires sont conservés, sans être agrégés aux résultats finaux.</p>
<h2>Vérification des écarts</h2><ul>
<li>Suite hors DB sur le code final : 5 220 réussis, 14 ignorés, une dépréciation rdflib dans le code tiers inchangé (<a href="offline-final.log">journal</a>). Ruff, formatage, ty et tous les hooks passent (<a href="precommit-final.log">journal</a>). L’import effectif du module de la candidate est contrôlé par un plugin de test.</li>
<li><a href="differential-fusion-hardened.json">3 000 exemples générés</a>, graine fixe : dictionnaires, fragments, VertexRep et mélanges invalides ; valeurs, types, bits flottants, ordre, multiplicités, erreurs et arguments, mutations des entrées et topologie des références partagées. Aucun écart détecté dans ce domaine. Deux propriétés de régression à 500 exemples complètent les cas explicites.</li>
<li>Deux vrais contre-exemples ont été trouvés puis corrigés : un hash d’identité ajoutant None à la liste (<a href="stateful-hash-before-fix.json">avant</a>, <a href="stateful-hash-final.json">après</a>) ; une clé personnalisée remplissant un fragment vide avant sa fusion (<a href="stateful-key-before-fix.json">avant</a>, <a href="stateful-key-after-fix.json">après</a>). Le corpus aléatoire ne générait pas ces callbacks ; les tests explicites les couvrent maintenant.</li>
<li>Les cas valides, imbriqués, erreurs et transformations vérifient aussi des attentes indépendantes de la référence, puis toutes les données brutes des résultats Pydantic et les références partagées. Une égalité de cardinalités seule n’est jamais le critère.</li>
<li><a href="diagnostic-final-comparison.json">Diagnostics</a> : types d’exception, messages et indices de document identiques dans le cas contrôlé. Les piles brutes gardent des différences attendues de chemins, fonctions et lignes ; elles sont archivées. La substitution des racines de source dans le banc est limitée aux champs traceback.</li>
</ul>
<h2>Ingestion complète sur FalkorDB</h2><p>Quatre paires sur 100 000 documents CSV/JSONL, serveur C 4.22.3 neuf et processus client neuf à chaque passage, aucun lecteur concurrent. Schéma, données et options identiques. Lecture, transformations et écritures incluses dans le temps ; vérification exhaustive ultérieure exclue. Les {e2e['validated_items']:,} Item, {e2e['validated_categories']:,} Category et {e2e['validated_edges']:,} arêtes lus au total ont les valeurs et types attendus ; empreintes typées identiques entre les huit passages. Index et contraintes vérifiés. <a href="e2e-summary.json">Résultats et liens vers chaque passage</a>, <a href="e2e-protocol-before-runs.txt">protocole</a>.</p>
<table><thead><tr><th>Mesure</th><th>Baisse médiane</th><th>Accélérations des quatre paires</th></tr></thead><tbody>{e2e_rows}</tbody></table>
<p>Avec quatre paires, cette campagne reste exploratoire pour les petits gains. Les VmHWM et memory.peak sont des maxima de vie processus/cgroup, incluant le démarrage ; ils sont capturés avant/après ingestion et avant lecture exhaustive. Ils ne mesurent pas un pic exclusif du casting et ne permettent pas d’affirmer une réduction mémoire causale.</p>
<p>Un écart de métadonnées a été détecté par l’oracle strict : l’ordre d’énumération des deux labels d’index varie entre essais, y compris sur la référence. Les listes brutes sont conservées dans <a href="index-listing-order-audit.json">cet audit</a>. L’égalité des lignes complètes est vérifiée comme ensemble ; l’ordre des propriétés à l’intérieur de chaque ligne reste vérifié. Les empreintes des données du graphe n’ont subi aucune normalisation.</p>
<h2>Essais écartés et limites</h2><p>Les variantes singleton et filtrage large des vides ont été écartées : complexité sans bénéfice macro robuste, ou régressions micro sur certaines charges. La spécialisation dict seule ne franchissait pas le seuil. Les données de ces essais restent dans <a href="experiments/">experiments</a>, ainsi que la campagne CPU2 précédant la seconde correction sémantique. Les résultats anciens de la combinaison finale sur deux CPU, et les microbenchmarks antérieurs au dernier durcissement, sont exploratoires ; ils ne soutiennent pas les chiffres finaux. Aucun résultat défavorable n’a été retiré pour améliorer la médiane.</p>
<p>La mesure précédente de 59–75 % autour du casting était une durée murale, pas une attribution CPU exclusive. Le pilote avec deux processus utilisait une configuration déjà disponible et n’est pas un bénéfice du patch. La machine reste partagée, l’affinité ne réserve pas les cœurs et les fréquences ne sont pas figées. Les données synthétiques et Python 3.11.13 ne couvrent pas toutes les charges, les autres versions Python, tous les callbacks possibles ni tous les backends. Préserver le comportement existant peut aussi préserver ses limites, notamment la mutation déjà existante d’une observation ayant des fragments sans identité avant elle.</p>
<p>Les durées de profil instrumenté restent séparées des mesures de performance. Les traces cProfile des threads se recouvrent ; leurs temps d’attente ne doivent pas être additionnés comme du CPU. Les métadonnées de distribution installée indiquent encore 1.24.0 dans le venv figé, tandis que les imports contrôlés utilisent les sources 1.24.1. Entre ces versions, les dépendances et leur verrouillage ne changent que la chaîne de version GraFlo ; le même venv en lecture seule sert aux deux côtés. Ce décalage est explicitement enregistré dans l’environnement.</p>
<p>Publication retenue : aucun push ni PR avant le 30 octobre 2026, Europe/Madrid. <a href="pr-draft.txt">Brouillon de PR</a>, <a href="contribution.patch">patch</a>, <a href="reproduce.txt">reproduction</a>. Rien n’est programmé pour une publication automatique.</p></html>'''
(p/'rapport.html').write_text(text)
(p/'acceptance-final.json').write_text(json.dumps({'accepted':accepted,'persistent':passed(persistent),'fresh_processes':passed(fresh),'aa_ci_includes_one':aa['cpu_speedup_ci95'][0]<=1<=aa['cpu_speedup_ci95'][1],'reliable_matrix_regression':any(s['reliable_cpu_regression_over_2_percent'] for s in matrix['conditions'])},indent=2)+'\n')
print('Accepted:',accepted)
